from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from pathlib import Path
from xml.sax.saxutils import escape

out=Path('output/pdf/Smart_Collar_Guia_colaboradores_VS_Code.pdf')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleSC',fontName='Helvetica-Bold',fontSize=25,leading=29,textColor=colors.HexColor('#143f4b'),spaceAfter=12))
styles.add(ParagraphStyle(name='SubSC',fontSize=11,leading=16,textColor=colors.HexColor('#52717b'),spaceAfter=18))
styles.add(ParagraphStyle(name='StepSC',fontName='Helvetica-Bold',fontSize=12,leading=16,textColor=colors.HexColor('#143f4b'),spaceBefore=13,spaceAfter=5))
styles.add(ParagraphStyle(name='BodySC',fontSize=10.5,leading=15,spaceAfter=7))
styles.add(ParagraphStyle(name='CodeSC',fontName='Courier',fontSize=9,leading=14,backColor=colors.HexColor('#edf3f5'),borderPadding=9,spaceBefore=12,spaceAfter=14))
styles.add(ParagraphStyle(name='NoteSC',fontSize=10,leading=14,textColor=colors.HexColor('#143f4b'),backColor=colors.HexColor('#e9f5f0'),borderPadding=10,spaceBefore=9,spaceAfter=12))
story=[]
def p(t): story.append(Paragraph(t,styles['BodySC']))
def step(t): story.append(Paragraph(t,styles['StepSC']))
def code(t): story.append(Paragraph(escape(t).replace('\n','<br/>'),styles['CodeSC']))
def note(t): story.append(Paragraph(t,styles['NoteSC']))
def title(n,t,sub):
    if story: story.append(PageBreak())
    story.append(Paragraph('SMART COLLAR / GUÍA PARA EL EQUIPO',styles['SubSC']))
    story.append(Paragraph(f'{n}. {t}',styles['TitleSC']))
    story.append(Paragraph(sub,styles['SubSC']))

title(1,'Clonar y abrir el proyecto','Desde la invitación aceptada hasta tener tu copia en VS Code. Windows · 3 de noviembre de 2026')
p('Esta guía utiliza los botones de VS Code para crear commits y subir cambios. No necesitas ejecutar comandos git add, git commit o git push.')
step('Antes de comenzar')
p('Acepta la invitación e inicia sesión en GitHub con tu propia cuenta. Comprueba que puedes abrir el repositorio. Ricardo debe haber subido los últimos avances para que puedas descargarlos.')
p('Instala <b>Git para Windows</b>, <b>VS Code</b> y <b>Node.js LTS compatible con Vite</b> (22.12 o posterior). Si acabas de instalarlos, cierra y abre VS Code.')
p('<link href="https://git-scm.com/downloads/win" color="#007f71">Descargar Git</link> · <link href="https://code.visualstudio.com/Download" color="#007f71">Descargar VS Code</link> · <link href="https://nodejs.org/en/download" color="#007f71">Descargar Node.js</link>')
step('1. Abre la opción de clonar')
p('En VS Code, pulsa <b>Ctrl + Shift + P</b>. Escribe <b>Git: Clone</b> o <b>Git: Clonar</b> y selecciona el comando.')
step('2. Pega la dirección del repositorio')
code('https://github.com/RicardoNV/pmbook-proyecto.git')
p('Pulsa Enter. Si se solicita iniciar sesión, autoriza el acceso desde el navegador usando la cuenta que aceptó la invitación.')
step('3. Elige el Escritorio y abre la carpeta')
p('En el selector de carpetas, elige <b>Escritorio</b> y confirma la ubicación. VS Code creará dentro la carpeta <b>pmbook-proyecto</b>. Cuando termine, pulsa <b>Abrir / Open</b>. Si aparece el aviso de confianza, acepta solo si reconoces este repositorio del equipo.')
note('<b>Resultado:</b> en el Explorador de VS Code deben aparecer index.html, login.html, package.json y assets. La clonación también descarga el historial y conecta tu copia con GitHub; no selecciones Inicializar repositorio ni descargues un ZIP para este flujo.')

title(2,'Preparar Smart Collar','Esta configuración se realiza una vez en cada computadora.')
step('4. Instala las dependencias')
p('Abre <b>Terminal / Nueva terminal</b>. Confirma que la ruta termina en pmbook-proyecto y ejecuta:')
code('npm ci')
p('Este comando instala las versiones del proyecto. Si PowerShell bloquea npm.ps1, utiliza <b>npm.cmd ci</b>. No subas node_modules a GitHub.')
step('5. Crea la configuración local de Supabase')
p('En el Explorador, copia <b>.env.example</b>, pégalo en la misma carpeta y renombra la copia como <b>.env.local</b>. Abre el archivo y completa:')
code('VITE_SUPABASE_URL=https://xwztaqpjhafqbdsbhlga.supabase.co\nVITE_SUPABASE_PUBLISHABLE_KEY=PEGA_LA_CLAVE_PUBLICABLE')
p('Pide a Ricardo la clave publicable y sustituye el texto de ejemplo. Guarda con <b>Ctrl + S</b>. No necesitas contraseñas de la base de datos ni claves secretas. El archivo .env.local está excluido de Git.')
p('La base de datos ya está preparada: <b>no vuelvas a ejecutar las migraciones SQL</b>. Puedes registrarte con tu propio correo para probar tus mascotas.')
step('6. Ejecuta la página')
code('npm run dev')
p('Abre la URL que muestre la terminal, normalmente <b>http://127.0.0.1:5174</b>. Mantén esa terminal abierta mientras trabajas. Para detener el servidor, pulsa <b>Ctrl + C</b>.')
step('Si Git solicita nombre y correo al confirmar')
p('Aunque no se necesite distinguir autores, Git exige una identidad para crear commits. Configúrala una sola vez desde la terminal de VS Code:')
code('git config user.name "Tu nombre"\ngit config user.email "tu-correo@example.com"')
p('Estos valores se aplican a este repositorio. Puedes usar el correo privado noreply de tu cuenta de GitHub. Esta configuración no sustituye el inicio de sesión ni otorga permisos.')

title(3,'Editar y hacer un commit','Todo el proceso de Git de esta página se realiza desde la interfaz de VS Code.')
step('7. Actualiza tu copia antes de una tarea nueva')
p('Con tus cambios anteriores ya confirmados, pulsa el nombre de la rama en la esquina inferior izquierda y selecciona <b>main</b>. Abre <b>Ctrl + Shift + P / Git: Pull</b> para descargar la versión actual. Si cambió package-lock.json, ejecuta de nuevo npm ci.')
step('8. Crea una rama para tu tarea')
p('Pulsa nuevamente <b>main</b> en la esquina inferior izquierda y selecciona <b>Create new branch / Crear nueva rama</b>. También puedes buscar <b>Git: Create Branch</b> en la paleta.')
code('mejora/perfil-mascota')
p('Es un ejemplo: elige un nombre corto para tu tarea. Comprueba que aparezca abajo a la izquierda antes de editar. La rama permite revisar tus cambios antes de incorporarlos a main.')
step('9. Edita, guarda y prueba')
p('Modifica los archivos necesarios y guárdalos con <b>Ctrl + S</b>. Revisa la página en el navegador. Antes de confirmar, comprueba la compilación en otra terminal:')
code('npm run build')
step('10. Revisa y prepara los archivos')
p('Pulsa <b>Ctrl + Shift + G</b> para abrir <b>Control de código fuente</b>. En <b>Cambios / Changes</b>, haz clic en cada archivo para ver sus diferencias. Pulsa el botón <b>+</b> junto a los archivos que sí pertenecen a tu tarea.')
p('Los archivos pasarán a <b>Cambios preparados / Staged Changes</b>. El botón <b>-</b> los retira de la preparación sin borrar tu edición. No uses Descartar cambios salvo que quieras perder esas modificaciones.')
step('11. Escribe el mensaje y confirma')
p('En el cuadro superior escribe un mensaje concreto, por ejemplo <b>Mejora el selector de mascotas</b>. Pulsa <b>Confirmación / Commit</b> (el botón con la palomita).')
note('<b>Guardar archivo:</b> actualiza tu copia. <b>Commit:</b> registra una versión local. El commit todavía no está en GitHub; falta el siguiente paso.')

title(4,'Subir y compartir cambios','Publicar la rama, revisar el resultado y continuar trabajando.')
step('12. Sube el commit desde VS Code')
p('La primera vez, en Control de código fuente pulsa <b>Publicar rama / Publish Branch</b>. Si pregunta por un remoto, elige <b>origin</b>. Autoriza GitHub con tu propia cuenta si lo solicita.')
p('Para los siguientes commits de esa misma rama, abre <b>Ctrl + Shift + P / Git: Push</b>. También puedes usar <b>Sincronizar cambios / Sync Changes</b>, que primero descarga cambios remotos y después sube los tuyos.')
note('Selecciona <b>Publicar rama</b>, no <b>Publish to GitHub / Publicar en GitHub</b>: ya estamos trabajando con un repositorio existente, no creando otro.')
step('13. Comprueba que llegó a GitHub')
p('Abre <link href="https://github.com/RicardoNV/pmbook-proyecto" color="#007f71">github.com/RicardoNV/pmbook-proyecto</link>. En el selector de ramas elige la tuya y comprueba el mensaje de tu último commit. Compartir la rama ya permite que Ricardo revise el trabajo.')
step('14. Entrega la rama para integrarla')
p('En GitHub pulsa <b>Compare &amp; pull request</b>, o <b>Pull requests / New pull request</b>. Selecciona <b>base: main</b> y <b>compare: tu rama</b>, explica el cambio y pulsa <b>Create pull request</b>. Ricardo podrá revisarlo e integrarlo.')
p('Los commits se hicieron desde VS Code; este paso de revisión se realiza en GitHub. Después de integrar, vuelve a main en VS Code y ejecuta <b>Git: Pull</b> desde la paleta antes de crear otra rama.')
step('Si algo no funciona')
p('<b>No puedes clonar o subir:</b> comprueba que aceptaste la invitación y que estás conectado con esa misma cuenta. <b>No aparecen cambios:</b> guarda los archivos y verifica que abriste la carpeta correcta. <b>Hay conflictos:</b> no fuerces el envío; avisa a Ricardo para revisar juntos los archivos afectados.')
p('<b>Netlify:</b> subir commits no publica automáticamente la página. Ricardo genera dist con npm run build y lo carga manualmente al sitio.')
step('Consulta rápida')
p('<b>Ctrl + Shift + P:</b> comandos de VS Code. <b>Ctrl + Shift + G:</b> cambios y commits. <b>Ctrl + S:</b> guardar. El historial local está en .git y los commits subidos también están en GitHub.')
p('<font size="8">Fuentes: <link href="https://code.visualstudio.com/docs/sourcecontrol/repos-remotes">VS Code: repositorios y remotos</link> · <link href="https://code.visualstudio.com/docs/sourcecontrol/quickstart">VS Code: commits</link> · <link href="https://docs.github.com/en/get-started/git-basics/caching-your-github-credentials-in-git">GitHub: autenticación</link>. Los nombres de botones pueden variar según idioma y versión.</font>')

def footer(c,doc):
    w,h=doc.pagesize
    c.setStrokeColor(colors.HexColor('#dce6e9'));c.line(44,43,w-44,43)
    c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#52717b'))
    c.drawString(44,29,'SMART COLLAR · Colaboración desde VS Code')
    c.drawRightString(w-44,29,f'{doc.page} / 4')
SimpleDocTemplate(str(out),pagesize=(595.28,841.89),rightMargin=44,leftMargin=44,topMargin=38,bottomMargin=57,title='Smart Collar - Guía de colaboración con VS Code',author='Equipo Smart Collar').build(story,onFirstPage=footer,onLaterPages=footer)
print(out.resolve())

